        '<ALL>' as SECURITY_DEPARTMENT,
        '<ALL>' as SECURITY_OFFICE
    FROM {{ ref('COMMON__CRM__CONTRACT_SUMMARY_DETAILS') }} contract_summary
    LEFT JOIN {{ ref('COMMON__SAPH__SALES_ORDER_BILLING_PLAN') }} sabp ON contract_summary.CNT_CONTRUCTNUMBER = sabp.CONTRACT_NUMBER
    left outer join security_cte
        on sabp.VBAP_COST_CENTER=security_cte.COST_CENTER_CODE
    left outer join profit_center
        on SABP.PROFIT_CENTER=profit_center.PROFIT_CENTER_CODE
),

